DROP TABLE IF EXISTS `tenencia`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tenencia` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `persona_cedula` varchar(20) NOT NULL,
  `unidad_id` int(11) NOT NULL,
  `rol` enum('propietario','inquilino','residente') NOT NULL DEFAULT 'propietario',
  `fecha_inicio` date DEFAULT NULL,
  `estado` enum('activo','inactivo') NOT NULL DEFAULT 'activo',
  PRIMARY KEY (`id`),
  KEY `tenencia_persona` (`persona_cedula`),
  KEY `tenencia_unidad` (`unidad_id`),
  CONSTRAINT `tenencia_ibfk_1` FOREIGN KEY (`persona_cedula`) REFERENCES `personas` (`cedula`) ON DELETE CASCADE,
  CONSTRAINT `tenencia_ibfk_2` FOREIGN KEY (`unidad_id`) REFERENCES `unidades` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

